import { describe, it, expect } from "vitest";
import { executeCommands } from "./mars-rover.js";

describe("Mars Rover", () => {
  // Rule 5: commands executed sequentially (empty case)
  it.todo("should leave the rover unchanged for an empty command string — (0, 0, N) stays (0, 0, N)");

  // Rule 2: Turning left
  it.todo("should turn left from N to W — (0, 0, N) with 'L' gives (0, 0, W)");
  it.todo("should turn left from W to S — (0, 0, W) with 'L' gives (0, 0, S)");
  it.todo("should turn left from S to E — (0, 0, S) with 'L' gives (0, 0, E)");
  it.todo("should turn left from E to N — (0, 0, E) with 'L' gives (0, 0, N)");

  // Rule 3: Turning right (spec typo N→E→S→E→N is read as N→E→S→W→N)
  it.todo("should turn right from N to E — (0, 0, N) with 'R' gives (0, 0, E)");
  it.todo("should turn right from E to S — (0, 0, E) with 'R' gives (0, 0, S)");
  it.todo("should turn right from S to W — (0, 0, S) with 'R' gives (0, 0, W)");
  it.todo("should turn right from W to N — (0, 0, W) with 'R' gives (0, 0, N)");

  // Rule 4: Moving forward
  it.todo("should move forward north — (0, 0, N) with 'F' gives (0, 1, N)");
  it.todo("should move forward east — (0, 0, E) with 'F' gives (1, 0, E)");
  it.todo("should move forward south — (0, 0, S) with 'F' gives (0, -1, S)");
  it.todo("should move forward west — (0, 0, W) with 'F' gives (-1, 0, W)");

  // Constraint: coordinates can be negative
  it.todo("should allow negative coordinates — (0, 0, S) with 'FF' gives (0, -2, S)");

  // Rule 5: sequences of commands
  it.todo("should turn around with two left turns — (0, 0, N) with 'LL' gives (0, 0, S)");
  it.todo("should return to the original direction after four right turns — (0, 0, N) with 'RRRR' gives (0, 0, N)");
  it.todo("should execute a complex sequence — (0, 0, N) with 'FFRFF' gives (2, 2, E)");
  it.todo("should trace three sides of a 1x1 square — (0, 0, N) with 'FRFRFRF' gives (0, 0, W)");
  it.todo("should execute a mixed sequence from the rule example — (0, 0, N) with 'FFRFLF' gives (1, 3, N)");
});

